'use client'

import * as React from 'react'

import { Field } from '@chakra-ui/react'

import type { BaseFieldProps } from './types'

export interface FieldRootProps extends BaseFieldProps {
  invalid: boolean
  errorText?: string
  children: React.ReactNode
}

/**
 * Shared shell for every field component: renders the Chakra `Field.Root`
 * with label, the control (`children`), and helper/error text.
 */
export function FieldRoot(props: FieldRootProps) {
  const {
    label,
    help,
    orientation,
    required,
    rootProps,
    invalid,
    errorText,
    children,
  } = props

  return (
    <Field.Root
      orientation={orientation}
      required={required}
      invalid={invalid}
      {...rootProps}
    >
      {label && <Field.Label>{label}</Field.Label>}
      {children}
      {help && !invalid && <Field.HelperText>{help}</Field.HelperText>}
      {invalid && errorText && <Field.ErrorText>{errorText}</Field.ErrorText>}
    </Field.Root>
  )
}

'use client'

import * as React from 'react'

import { createListCollection } from '@chakra-ui/react'

import { Select } from '#registry/default/ui/select/index.ts'

import { useFieldContext } from '../form-context'
import { getErrorText } from '../utils'
import { FieldRoot } from './field-root'
import type { BaseFieldProps } from './types'

export interface SelectFieldOption {
  label: string
  value: string
}

/** A list of select options. */
export type FieldOptions = SelectFieldOption[]

export interface SelectFieldProps extends BaseFieldProps {
  options: SelectFieldOption[]
  multiple?: boolean
  placeholder?: string
}

/**
 * Select field backed by the Chakra 3 collection API. Adapts the scalar field
 * value (single select) to the array value the underlying `Select` expects.
 */
export function SelectField(props: SelectFieldProps) {
  const {
    label,
    help,
    orientation,
    required,
    rootProps,
    options,
    multiple,
    placeholder,
  } = props

  const field = useFieldContext<string | string[]>()
  const errorText = getErrorText(field.state.meta.errors)
  const invalid = field.state.meta.isTouched && !!errorText

  const collection = React.useMemo(
    () => createListCollection({ items: options }),
    [options],
  )

  const value = multiple
    ? ((field.state.value as string[] | undefined) ?? [])
    : field.state.value
      ? [field.state.value as string]
      : []

  return (
    <FieldRoot
      label={label}
      help={help}
      orientation={orientation}
      required={required}
      rootProps={rootProps}
      invalid={invalid}
      errorText={errorText}
    >
      <Select.Root
        name={field.name}
        multiple={multiple}
        collection={collection}
        value={value}
        onValueChange={({ value }) =>
          field.handleChange(multiple ? value : (value[0] ?? ''))
        }
        onInteractOutside={() => field.handleBlur()}
      >
        <Select.Trigger>
          <Select.ValueText placeholder={placeholder} />
        </Select.Trigger>
        <Select.Content portalled={false}>
          {collection.items.map((item) => (
            <Select.Item key={item.value} item={item}>
              {item.label}
            </Select.Item>
          ))}
        </Select.Content>
      </Select.Root>
    </FieldRoot>
  )
}

'use client'

import * as React from 'react'

import { Field } from '@chakra-ui/react'

import { Switch } from '#registry/default/ui/switch/index.ts'

import { useFieldContext } from '../form-context'
import { getErrorText } from '../utils'
import type { BaseFieldProps } from './types'

export interface SwitchFieldProps
  extends
    BaseFieldProps,
    Omit<
      React.ComponentProps<typeof Switch>,
      'checked' | 'onCheckedChange' | 'onBlur' | keyof BaseFieldProps
    > {}

/**
 * Boolean toggle field. Renders the label beside the switch (horizontal by
 * default, matching the common settings/notification layout).
 */
export function SwitchField(props: SwitchFieldProps) {
  const {
    label,
    help,
    orientation = 'horizontal',
    required,
    rootProps,
    ...rest
  } = props

  const field = useFieldContext<boolean>()
  const errorText = getErrorText(field.state.meta.errors)
  const invalid = field.state.meta.isTouched && !!errorText

  return (
    <Field.Root
      orientation={orientation}
      required={required}
      invalid={invalid}
      {...rootProps}
    >
      {label && <Field.Label>{label}</Field.Label>}
      <Switch
        name={field.name}
        checked={field.state.value ?? false}
        onCheckedChange={({ checked }) => field.handleChange(checked)}
        onBlur={() => field.handleBlur()}
        {...rest}
      />
      {help && !invalid && <Field.HelperText>{help}</Field.HelperText>}
      {invalid && errorText && <Field.ErrorText>{errorText}</Field.ErrorText>}
    </Field.Root>
  )
}

'use client'

import * as React from 'react'

import { InputGroup } from '#registry/default/ui/input-group/index.ts'
import { Input } from '#registry/default/ui/input/index.ts'
import { PasswordInput } from '#registry/default/ui/password-input/index.ts'

import { useFieldContext } from '../form-context'
import { getErrorText } from '../utils'
import { FieldRoot } from './field-root'
import type { BaseFieldProps } from './types'

export interface TextFieldProps
  extends
    BaseFieldProps,
    Omit<
      React.ComponentProps<typeof Input>,
      'value' | 'onChange' | 'onBlur' | 'type' | 'form'
    > {
  type?: 'text' | 'email' | 'password' | 'tel' | 'url'
  startElement?: React.ReactNode
  endElement?: React.ReactNode
  /** Called in addition to the field's own change handler. */
  onChange?: (e: React.ChangeEvent<HTMLInputElement>) => void
}

/**
 * Text input field, covering text/email/password/tel/url. `type="password"`
 * uses `PasswordInput` (with the show/hide toggle). `startElement`/`endElement`
 * wrap the control in an `InputGroup`.
 */
export const TextField = React.forwardRef<HTMLInputElement, TextFieldProps>(
  function TextField(props, ref) {
    const {
      label,
      help,
      orientation,
      required,
      rootProps,
      type = 'text',
      startElement,
      endElement,
      onChange,
      ...inputProps
    } = props

    const field = useFieldContext<string>()
    const errorText = getErrorText(field.state.meta.errors)
    const invalid = field.state.meta.isTouched && !!errorText

    const commonProps = {
      ref,
      id: field.name,
      name: field.name,
      value: field.state.value ?? '',
      onChange: (e: React.ChangeEvent<HTMLInputElement>) => {
        field.handleChange(e.currentTarget.value)
        onChange?.(e)
      },
      onBlur: field.handleBlur,
      ...inputProps,
    }

    const control =
      type === 'password' ? (
        <PasswordInput {...commonProps} />
      ) : (
        <Input type={type} {...commonProps} />
      )

    return (
      <FieldRoot
        label={label}
        help={help}
        orientation={orientation}
        required={required}
        rootProps={rootProps}
        invalid={invalid}
        errorText={errorText}
      >
        {startElement || endElement ? (
          <InputGroup startElement={startElement} endElement={endElement}>
            {control}
          </InputGroup>
        ) : (
          control
        )}
      </FieldRoot>
    )
  },
)

