import * as React from 'react'

import { Textarea } from '@chakra-ui/react'

import { useFieldContext } from '../form-context'
import { getErrorText } from '../utils'
import { FieldRoot } from './field-root'
import type { BaseFieldProps } from './types'

export interface TextareaFieldProps
  extends
    BaseFieldProps,
    Omit<
      React.ComponentProps<typeof Textarea>,
      'value' | 'onChange' | 'onBlur' | 'form'
    > {
  /** Called in addition to the field's own change handler. */
  onChange?: (e: React.ChangeEvent<HTMLTextAreaElement>) => void
}

export const TextareaField = React.forwardRef<
  HTMLTextAreaElement,
  TextareaFieldProps
>(function TextareaField(props, ref) {
  const { label, help, orientation, required, rootProps, onChange, ...rest } =
    props

  const field = useFieldContext<string>()
  const errorText = getErrorText(field.state.meta.errors)
  const invalid = field.state.meta.isTouched && !!errorText

  return (
    <FieldRoot
      label={label}
      help={help}
      orientation={orientation}
      required={required}
      rootProps={rootProps}
      invalid={invalid}
      errorText={errorText}
    >
      <Textarea
        ref={ref}
        id={field.name}
        name={field.name}
        value={field.state.value ?? ''}
        onChange={(e) => {
          field.handleChange(e.currentTarget.value)
          onChange?.(e)
        }}
        onBlur={field.handleBlur}
        {...rest}
      />
    </FieldRoot>
  )
})

import type * as React from 'react'

import type { Field } from '@chakra-ui/react'

/**
 * Props shared by every field component. Each field reads its bound state from
 * `useFieldContext` and renders a Chakra `Field.Root` with label/help/error.
 */
export interface BaseFieldProps {
  /** Field label rendered above (or beside, when horizontal) the control. */
  label?: React.ReactNode
  /** Helper text shown below the control when the field is valid. */
  help?: React.ReactNode
  /** Label placement. `horizontal` uses the `--field-label-width` CSS var. */
  orientation?: 'horizontal' | 'vertical'
  /** Marks the field required (renders the required indicator). */
  required?: boolean
  /** Passthrough props for the wrapping `Field.Root` (e.g. `ps`, `width`). */
  rootProps?: React.ComponentProps<typeof Field.Root>
}

'use client'

import { Group, type GroupProps } from '@chakra-ui/react'

/**
 * Footer row for form actions (e.g. the submit button). Indents by the
 * `--field-label-width` so the actions line up under the field column in
 * horizontal-orientation forms; falls back to no indent when the var is unset.
 */
export function Footer(props: GroupProps) {
  return (
    <Group
      ps="calc(var(--field-label-width, 0px) + var(--chakra-spacing-2))"
      {...props}
    />
  )
}

'use client'

import * as React from 'react'

import { chakra } from '@chakra-ui/react'

/** Minimal structural shape of the app form used by `Form`. */
export interface FormLike {
  AppForm: React.ComponentType<React.PropsWithChildren<{}>>
  handleSubmit: () => unknown
}

export type FormProps<TForm extends FormLike> = {
  form: TForm
  children: React.ReactNode
} & Omit<React.ComponentProps<typeof chakra.form>, 'onSubmit'>

/**
 * Renders the `<form>` element and provides the app-form context in a single
 * wrapper, so registered form components (`form.SubmitButton`) work without a
 * separate `<form.AppForm>` and without threading the form through props.
 *
 * Generic over the form type so the concrete `useAppForm` generics are
 * forwarded (not widened to `any`).
 *
 *   <Form form={form}>
 *     <form.Layout>
 *       <form.AppField name="email">{(field) => <field.TextField />}</form.AppField>
 *       <form.SubmitButton>Save</form.SubmitButton>
 *     </form.Layout>
 *   </Form>
 */
export function Form<TForm extends FormLike>(props: FormProps<TForm>) {
  const { form, children, ...rest } = props

  return (
    <form.AppForm>
      <chakra.form
        noValidate
        onSubmit={(e) => {
          e.preventDefault()
          e.stopPropagation()
          void form.handleSubmit()
        }}
        {...rest}
      >
        {children}
      </chakra.form>
    </form.AppForm>
  )
}

// Factory hook + composition helpers
export { useAppForm, withForm, withFieldGroup } from './create-form'
export type { AnyAppForm } from './app-form'

// Contexts / hooks for building custom field & form components
export {
  fieldContext,
  formContext,
  useFieldContext,
  useFormContext,
} from './form-context'

// Field components
export { TextField, type TextFieldProps } from './fields/text-field'
export { TextareaField, type TextareaFieldProps } from './fields/textarea-field'
export {
  SelectField,
  type SelectFieldProps,
  type SelectFieldOption,
  type FieldOptions,
} from './fields/select-field'
export { SwitchField, type SwitchFieldProps } from './fields/switch-field'
export type { BaseFieldProps } from './fields/types'

// Form-level components
export { Form, type FormProps, type FormLike } from './form'
export { Layout, type LayoutProps } from './layout'
export { Footer } from './footer'
export { SubmitButton, type SubmitButtonProps } from './submit-button'

// Utilities
export { getErrorText } from './utils'

'use client'

import * as React from 'react'

import { Stack, type StackProps } from '@chakra-ui/react'

export interface LayoutProps extends StackProps {
  children: React.ReactNode
  /**
   * The width of the labels for horizontal-orientation form fields.
   * Sets `--field-label-width` CSS variable.
   */
  labelWidth?: string
}
/**
 * Vertical layout for form fields. Carries the `--field-label-width` CSS var
 * when a call-site sets it (used by horizontal-orientation fields). Does not
 * hardcode the var so an ancestor (e.g. `Card.Body`) can provide it instead.
 */
export function Layout(props: LayoutProps) {
  const { children, labelWidth, ...rest } = props
  return (
    <Stack
      gap="4"
      width="full"
      css={{
        '--field-label-width': labelWidth,
        ...rest.css,
      }}
      {...rest}
    >
      {children}
    </Stack>
  )
}

'use client'

import * as React from 'react'

import { Button, type ButtonProps } from '#registry/default/ui/button/index.ts'

import { useFormContext } from './form-context'

export interface SubmitButtonProps extends ButtonProps {
  loadingText?: React.ReactNode
  /**
   * Disable the button while the form is invalid/pristine. Defaults to `true`.
   * Set to `false` to always allow clicking (e.g. to trigger validation).
   */
  disableIfInvalid?: boolean
}

/**
 * Submit button bound to the app form from context (provided by `<Form>`).
 * Shows a loading state while submitting and (by default) disables until the
 * form can submit.
 */
export const SubmitButton = React.forwardRef<
  HTMLButtonElement,
  SubmitButtonProps
>(function SubmitButton(props, ref) {
  const {
    children = 'Submit',
    loadingText,
    disabled,
    disableIfInvalid = true,
    ...rest
  } = props

  const form = useFormContext()

  return (
    <form.Subscribe
      selector={(state) => ({
        isSubmitting: state.isSubmitting,
        canSubmit: state.canSubmit,
      })}
    >
      {({ isSubmitting, canSubmit }) => (
        <Button
          ref={ref}
          type="submit"
          variant="solid"
          colorPalette="accent"
          loading={isSubmitting}
          loadingText={loadingText}
          disabled={disabled ?? (disableIfInvalid ? !canSubmit : false)}
          {...rest}
        >
          {children}
        </Button>
      )}
    </form.Subscribe>
  )
})

/**
 * Extract a displayable error message from a field's `meta.errors`.
 *
 * TanStack Form surfaces errors from two sources with different shapes:
 * - Standard Schema (Zod) validators produce issue objects `{ message }`.
 * - Function validators produce plain strings.
 *
 * This normalizes both to the first error's message string.
 */
export function getErrorText(
  errors: ReadonlyArray<unknown> | undefined,
): string | undefined {
  const first = errors?.[0]
  if (first == null) {
    return undefined
  }
  if (typeof first === 'string') {
    return first
  }
  return (first as { message?: string }).message
}
